    private sealed class DirectoryPolicy:ISecretDirectoryPolicy{public void EnsurePrivate(string directory)=>Directory.CreateDirectory(directory);}
    private sealed class Protector:ISecretProtector
    {
        private static readonly byte[] Key=Enumerable.Repeat((byte)19,32).ToArray();public int OpenCount;
        public byte[] Protect(ReadOnlySpan<byte> plain){byte[] result=new byte[plain.Length+28];RandomNumberGenerator.Fill(result.AsSpan(0,12));using var cipher=new AesGcm(Key,16);cipher.Encrypt(result.AsSpan(0,12),plain,result.AsSpan(28),result.AsSpan(12,16));return result;}
        public byte[] Unprotect(ReadOnlySpan<byte> encrypted){OpenCount++;byte[] result=new byte[encrypted.Length-28];using var cipher=new AesGcm(Key,16);cipher.Decrypt(encrypted[..12],encrypted[28..],encrypted.Slice(12,16),result);return result;}
    }
    private sealed class Fixture:IDisposable
    {
        public string Root{get;}=Path.Combine(Path.GetTempPath(),"kuaiyi-settings-tests-"+Guid.NewGuid().ToString("N"));
        public SettingsStore Store{get;}public SecretFileStore Secrets{get;}public Protector Protector{get;}=new();public SettingsCoordinator Coordinator{get;}
        public Fixture(){Store=new(Path.Combine(Root,"config"));Secrets=new(Path.Combine(Root,"secrets"),Protector,new DirectoryPolicy());Coordinator=new(Store,Secrets);}
        public void Dispose(){if(Directory.Exists(Root))Directory.Delete(Root,true);}
        public async Task<SettingsSnapshot> Seed(){using var d=await Coordinator.OpenDraftAsync();d.Update(s=>s with{Profiles=[new(){Id="public",Name="公开合成配置",BaseUrl="https://public.invalid/v1",Model="public-test-model"}],ActiveProfileId="public"});d.SetKey("public","public-SYNTHETIC-KEY-A-849752"u8);return await Coordinator.SaveAsync(d);}
    }
    [Fact]public void DefinitionExportsSameDefaultsAndRangeSchema()
    {var s=SettingsJson.Schema();Assert.True(JsonNode.DeepEquals(s,JsonNode.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"appsettings.schema.json")))));Assert.True(JsonNode.DeepEquals(s["default"],JsonNode.Parse(SettingsJson.Write(new()))));Assert.Equal(12,s["properties"]!["overlay"]!["properties"]!["fontSizeDip"]!["minimum"]!.GetValue<double>());Assert.Equal(22,s["properties"]!["overlay"]!["properties"]!["fontSizeDip"]!["maximum"]!.GetValue<double>());}
