    [Fact]public async Task CancelDiscardsChangesAndZerosActualDraftKeyWithoutChangingEffectiveOrReadingOldSecret()
    {
        using var f=new Fixture();var old=await f.Seed();byte[] file=await File.ReadAllBytesAsync(f.Store.PrimaryPath);using var d=await f.Coordinator.OpenDraftAsync();d.Update(s=>s with{Overlay=s.Overlay with{FontSizeDip=20}});d.SetKey("public","public-SYNTHETIC-UNSAVED-KEY"u8);byte[] actual=d.PendingKeyForTest("public")!;d.Dispose();Assert.All(actual,b=>Assert.Equal(0,b));Assert.Equal(file,await File.ReadAllBytesAsync(f.Store.PrimaryPath));Assert.Equal(old.Version,f.Coordinator.Effective!.Version);Assert.Equal(15,f.Coordinator.Effective.Data.Overlay.FontSizeDip);Assert.Equal(0,f.Protector.OpenCount);
    }
    [Fact]public async Task SavedChangesAreOneImmutableSnapshotWhileOldRequestSnapshotAndEncryptedBackupKeySurvive()
    {
        using var f=new Fixture();var old=await f.Seed();using var d=await f.Coordinator.OpenDraftAsync();d.Update(s=>s with{Overlay=s.Overlay with{FontSizeDip=19}});d.SetKey("public","public-SYNTHETIC-KEY-B-283651"u8);var saved=await f.Coordinator.SaveAsync(d);Assert.True(d.IsClosed);Assert.Equal(15,old.Data.Overlay.FontSizeDip);Assert.Equal(19,saved.Data.Overlay.FontSizeDip);Assert.Equal(saved.Version,f.Coordinator.Effective!.Version);Assert.NotEqual(old.Data.Profiles[0].SecretRef,saved.Data.Profiles[0].SecretRef);
        using var key=await f.Secrets.OpenAsync(old.Data.Profiles[0].SecretRef!);Assert.True(key.Bytes.Span.SequenceEqual("public-SYNTHETIC-KEY-A-849752"u8));SettingsJson.Read(await File.ReadAllBytesAsync(f.Store.BackupPath),out _);foreach(string file in Directory.GetFiles(f.Root,"*",SearchOption.AllDirectories)){byte[] bytes=await File.ReadAllBytesAsync(file);Assert.True(bytes.AsSpan().IndexOf("public-SYNTHETIC-KEY-A-849752"u8)<0);Assert.True(bytes.AsSpan().IndexOf("public-SYNTHETIC-KEY-B-283651"u8)<0);}
    }
    [Fact]public async Task ActualTempFlushedThenInjectedWriteFailurePreservesOldConfigAndSecretAndEffectiveSnapshot()
    {
        using var f=new Fixture();var old=await f.Seed();byte[] original=await File.ReadAllBytesAsync(f.Store.PrimaryPath);var failed=new SettingsStore(f.Store.DirectoryPath){WriteStageForTest=stage=>{if(stage==SettingsWriteStage.BeforePublish)throw new IOException("public synthetic disk-full boundary");}};var c=new SettingsCoordinator(failed,f.Secrets);using var d=await c.OpenDraftAsync();d.SetKey("public","public-SYNTHETIC-FAILURE-KEY"u8);await Assert.ThrowsAsync<IOException>(()=>c.SaveAsync(d));Assert.False(d.IsClosed);Assert.Equal(original,await File.ReadAllBytesAsync(f.Store.PrimaryPath));Assert.Equal(old.Version,c.Effective!.Version);Assert.Single(Directory.GetFiles(Path.Combine(f.Root,"secrets"),"*.bin"));Assert.Empty(Directory.GetFiles(f.Store.DirectoryPath,"secret-txn-*.json"));using var lease=await f.Secrets.OpenAsync(old.Data.Profiles[0].SecretRef!);Assert.True(lease.Bytes.Span.SequenceEqual("public-SYNTHETIC-KEY-A-849752"u8));
    }
    [Fact]public async Task ExplicitDeletionRevokesOldReferenceOnlyAfterCommitAndBackupCannotReenableIt()
    {
        using var f=new Fixture();var old=await f.Seed();using var d=await f.Coordinator.OpenDraftAsync();d.ClearKey("public");Assert.False(f.Secrets.IsRevoked(old.Data.Profiles[0].SecretRef!));await f.Coordinator.SaveAsync(d);Assert.True(f.Secrets.IsRevoked(old.Data.Profiles[0].SecretRef!));Assert.Empty(Directory.GetFiles(Path.Combine(f.Root,"secrets"),"*.bin"));await Assert.ThrowsAsync<CryptographicException>(()=>f.Secrets.OpenAsync(old.Data.Profiles[0].SecretRef!));await File.WriteAllTextAsync(f.Store.PrimaryPath,"{public-corrupt");using var recovery=await f.Coordinator.OpenDraftAsync();Assert.Equal(SettingsLoadState.RecoverableBackup,recovery.Basis.State);await Assert.ThrowsAsync<SettingsValidationException>(()=>f.Coordinator.SaveAsync(recovery,SettingsRecovery.UseBackup));recovery.ClearKey("public");await f.Coordinator.SaveAsync(recovery,SettingsRecovery.UseBackup);Assert.Null(f.Coordinator.Effective!.Data.Profiles[0].SecretRef);
    }
    [Fact]public async Task TwoIndependentCoordinatorsRejectStaleDraftAndNeverOverwriteWinner()
    {
        using var f=new Fixture();await f.Seed();var other=new SettingsCoordinator(new(f.Store.DirectoryPath),f.Secrets);using var a=await f.Coordinator.OpenDraftAsync();using var b=await other.OpenDraftAsync();a.Update(s=>s with{Overlay=s.Overlay with{FontSizeDip=16}});b.Update(s=>s with{Overlay=s.Overlay with{FontSizeDip=20}});await f.Coordinator.SaveAsync(a);await Assert.ThrowsAsync<SettingsConflictException>(()=>other.SaveAsync(b));Assert.Equal(16,(await f.Store.LoadAsync()).Data.Overlay.FontSizeDip);Assert.False(b.IsClosed);
    }
    [Fact]public async Task ActualFileSharingLeaseBlocksSecondWriterAndCancellationDoesNotPublish()
    {
        using var f=new Fixture();var old=await f.Seed();using var held=new FileStream(Path.Combine(f.Store.DirectoryPath,"settings.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None);using var cancel=new CancellationTokenSource();var blocked=f.Store.SaveAsync(old,old.Data with{Overlay=old.Data.Overlay with{FontSizeDip=21}},cancellation:cancel.Token);await Task.Delay(80);Assert.False(blocked.IsCompleted);cancel.Cancel();await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>blocked);held.Dispose();Assert.Equal(old.Version,(await f.Store.LoadAsync()).Version);
    }
