    [Fact]public async Task DamagedPrimaryRequiresExplicitChoiceAndPreservesValidBackupAndCorruptBytes()
    {
        using var f=new Fixture();var old=await f.Seed();using(var d=await f.Coordinator.OpenDraftAsync()){d.Update(s=>s with{Overlay=s.Overlay with{FontSizeDip=18}});await f.Coordinator.SaveAsync(d);}byte[] backup=await File.ReadAllBytesAsync(f.Store.BackupPath);const string corrupt="{public-damage";await File.WriteAllTextAsync(f.Store.PrimaryPath,corrupt);using var d2=await f.Coordinator.OpenDraftAsync();Assert.Equal(SettingsLoadState.RecoverableBackup,d2.Basis.State);await Assert.ThrowsAsync<SettingsRecoveryRequiredException>(()=>f.Coordinator.SaveAsync(d2));Assert.Equal(corrupt,await File.ReadAllTextAsync(f.Store.PrimaryPath));await f.Coordinator.SaveAsync(d2,SettingsRecovery.UseBackup);Assert.Equal(backup,await File.ReadAllBytesAsync(f.Store.BackupPath));Assert.Equal(corrupt,await File.ReadAllTextAsync(Assert.Single(Directory.GetFiles(f.Store.DirectoryPath,"settings.corrupt-*.json"))));Assert.Equal(old.Data.Profiles[0].SecretRef,(await f.Store.LoadAsync()).Data.Profiles[0].SecretRef);
    }
    [Fact]public async Task BothDamagedFilesStayUntilExplicitSafeDefaultsRecovery()
    {using var f=new Fixture();await f.Store.LoadAsync();await File.WriteAllTextAsync(f.Store.PrimaryPath,"primary-public-broken");await File.WriteAllTextAsync(f.Store.BackupPath,"backup-public-broken");var s=await f.Store.LoadAsync();Assert.Equal(SettingsLoadState.RecoverableDefaults,s.State);await Assert.ThrowsAsync<SettingsRecoveryRequiredException>(()=>f.Store.SaveAsync(s,new()));await f.Store.SaveAsync(s,new(),SettingsRecovery.UseDefaults);Assert.Equal(SettingsLoadState.Current,(await f.Store.LoadAsync()).State);Assert.Equal("backup-public-broken",await File.ReadAllTextAsync(f.Store.BackupPath));Assert.Equal("primary-public-broken",await File.ReadAllTextAsync(Assert.Single(Directory.GetFiles(f.Store.DirectoryPath,"settings.corrupt-*.json"))));}
    [Theory][InlineData(SettingsWriteStage.BeforePublish)][InlineData(SettingsWriteStage.AfterPublish)]public async Task RealIndependentChildKilledAtFlushedOrPublishedBoundaryRecoversWholeConfigAndDeletionTransaction(SettingsWriteStage stage)
    {
        using var f=new Fixture();var old=await f.Seed();string assembly=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../../tools/KuaiYi.SettingsStoreFixture/bin",new DirectoryInfo(AppContext.BaseDirectory).Parent!.Name,"net10.0/KuaiYi.SettingsStoreFixture.dll"));var info=new ProcessStartInfo(Environment.GetEnvironmentVariable("DOTNET_HOST_PATH")??"dotnet"){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardInput=true,RedirectStandardError=true};foreach(string arg in new[]{assembly,f.Root,stage.ToString()})info.ArgumentList.Add(arg);using var child=Process.Start(info)!;
        try{Assert.Equal("PUBLIC_STAGE="+stage,await child.StandardOutput.ReadLineAsync().WaitAsync(TimeSpan.FromSeconds(5)));child.Kill();await child.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(4));using var d=await f.Coordinator.OpenDraftAsync();Assert.Equal(stage==SettingsWriteStage.AfterPublish?18:15,d.Data.Overlay.FontSizeDip);Assert.Equal(stage==SettingsWriteStage.AfterPublish,f.Secrets.IsRevoked(old.Data.Profiles[0].SecretRef!));Assert.Empty(Directory.GetFiles(f.Store.DirectoryPath,"secret-txn-*.json"));if(stage==SettingsWriteStage.BeforePublish)Assert.NotEmpty(Directory.GetFiles(f.Store.DirectoryPath,"settings.tmp-*"));SettingsJson.Read(await File.ReadAllBytesAsync(f.Store.PrimaryPath),out _);}
        finally{if(!child.HasExited){child.Kill();await child.WaitForExitAsync();}}
    }
    [Fact]public async Task OpenAndSaveWhileOffNeverReadsOldKeysOrInvokesCaptureOrNetwork()
    {
        using var f=new Fixture();await f.Seed();var gate=new RuntimeGate();f.Coordinator.Committed+=(s,retired)=>{if(retired.HasDeletion)gate.Disable();gate.SetMode(s.Data.TriggerMode);};gate.SetSuspension(Suspension.Settings,true);using var d=await f.Coordinator.OpenDraftAsync();d.Update(s=>s with{TriggerMode=TriggerMode.Drop});await f.Coordinator.SaveAsync(d);gate.SetSuspension(Suspension.Settings,false);Assert.Equal(Activation.Off,gate.Snapshot.Activation);Assert.False(gate.TryBeginPassiveCapture(TriggerMode.Drop,out _));Assert.False(gate.TryStartRequest(Guid.NewGuid(),Guid.NewGuid(),null,out var identity,out _));Assert.False(gate.CanSend(identity,new(new Uri("https://public.invalid"))));Assert.Equal(0,f.Protector.OpenCount);
    }
    [Fact]public async Task SettingsSuspensionPreservesAlreadyAcceptedRequestAndImmutableConfiguration()
    {using var f=new Fixture();var old=await f.Seed();var gate=new RuntimeGate();var origin=new EndpointOrigin(new Uri("https://public.invalid"));gate.ConsentTo(origin);Assert.True(gate.TryEnable(origin,true));Assert.True(gate.TryStartRequest(Guid.NewGuid(),Guid.NewGuid(),null,out var identity,out var token));gate.SetSuspension(Suspension.Settings,true);using(var d=await f.Coordinator.OpenDraftAsync()){d.Update(s=>s with{Translation=s.Translation with{Preset=TranslationPreset.Plain}});await f.Coordinator.SaveAsync(d);}gate.SetSuspension(Suspension.Settings,false);Assert.True(gate.CanApply(identity));Assert.False(token.IsCancellationRequested);Assert.Equal(TranslationPreset.Faithful,old.Data.Translation.Preset);Assert.Equal(TranslationPreset.Plain,f.Coordinator.Effective!.Data.Translation.Preset);gate.Disable();}
