    {using var f=new Fixture();string reference=await f.Secrets.SaveNewAsync("public-SYNTHETIC-LEASE"u8.ToArray());var lease=await f.Secrets.OpenAsync(reference);Assert.True(System.Runtime.InteropServices.MemoryMarshal.TryGetArray(lease.Bytes,out var array));lease.Dispose();Assert.All(array.Array!,b=>Assert.Equal(0,b));Assert.Throws<ObjectDisposedException>(()=>lease.Bytes);await f.Secrets.RevokeAsync(reference);await Assert.ThrowsAsync<CryptographicException>(()=>f.Secrets.OpenAsync(reference));}
