    {using var f=new Fixture();using(var d=await f.Coordinator.OpenDraftAsync()){d.Update(s=>s with{Profiles=[new(){Id="public",Model="public-model",BaseUrl="https://public.invalid",Authentication=ApiAuthentication.None}],ActiveProfileId="public"});await f.Coordinator.SaveAsync(d);}var gate=new RuntimeGate();var origin=new EndpointOrigin(new Uri("https://public.invalid"));gate.ConsentTo(origin);Assert.True(gate.TryEnable(origin,true));Assert.True(gate.TryStartRequest(Guid.NewGuid(),Guid.NewGuid(),null,out _,out var token));SettingsChange? observed=null;f.Coordinator.Committed+=(_,change)=>{observed=change;if(change.DeletedProfiles.Contains("public"))gate.Disable();};using(var d=await f.Coordinator.OpenDraftAsync()){d.Update(s=>s with{Profiles=[],ActiveProfileId=null});await f.Coordinator.SaveAsync(d);}Assert.True(token.IsCancellationRequested);Assert.Contains("public",observed!.DeletedProfiles);Assert.Empty(observed.DeletedSecrets);}
