    [Fact]public void PositionRestoresAgainstCurrentTopologyAndDpiIncludingMissingMonitorAndNegativeOrigin()
    {var a=new MonitorGeometry("a",new(-1920,0,0,1040),new(1));var b=new MonitorGeometry("b",new(0,-400,2560,1040),new(2));var anchor=OverlayPositionMapper.Restore(null,[a,b],"a");var saved=OverlayPositionMapper.Capture(anchor,a);Assert.Equal(anchor,OverlayPositionMapper.Restore(saved,[a,b],"a"));var restored=OverlayPositionMapper.Restore(saved,[b],"b");Assert.True(b.WorkArea.Contains(restored));Assert.Equal(96,restored.Width);Assert.Throws<SettingsValidationException>(()=>OverlayPositionMapper.Restore(saved with{X=double.NaN},[b],"b"));}
